import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] s = new long[n], dur = new long[n], v = new long[n];
        for (int i = 0; i < n; i++) s[i] = nextLong();
        for (int i = 0; i < n; i++) dur[i] = nextLong();
        for (int i = 0; i < n; i++) v[i] = nextLong();
        long[][] jobs = new long[n][];
        for (int i = 0; i < n; i++) jobs[i] = new long[] {s[i] + dur[i], s[i], v[i]};
        Arrays.sort(jobs, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : x[1] != y[1] ? Long.compare(x[1], y[1]) : Long.compare(x[2], y[2]));
        long[] ends = new long[n], dp = new long[n + 1];
        for (int i = 0; i < n; i++) ends[i] = jobs[i][0];
        for (int i = 0; i < n; i++) {
            // Screenings that end strictly before this one starts.
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] < jobs[i][1]) lo = mid + 1;
                else hi = mid;
            }
            dp[i + 1] = Math.max(dp[i], dp[lo] + jobs[i][2]);
        }
        System.out.println(dp[n]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n := readInt()
	s, dur, v := make([]int, n), make([]int, n), make([]int, n)
	for i := range s {
		s[i] = readInt()
	}
	for i := range dur {
		dur[i] = readInt()
	}
	for i := range v {
		v[i] = readInt()
	}
	type job struct{ end, start, value int }
	jobs := make([]job, n)
	for i := range jobs {
		jobs[i] = job{s[i] + dur[i], s[i], v[i]}
	}
	sort.Slice(jobs, func(a, b int) bool {
		x, y := jobs[a], jobs[b]
		if x.end != y.end {
			return x.end < y.end
		}
		if x.start != y.start {
			return x.start < y.start
		}
		return x.value < y.value
	})
	ends := make([]int, n)
	for i, j := range jobs {
		ends[i] = j.end
	}
	dp := make([]int, n+1)
	for i, j := range jobs {
		// Screenings that end strictly before this one starts.
		compatible := sort.SearchInts(ends, j.start)
		dp[i+1] = max(dp[i], dp[compatible]+j.value)
	}
	fmt.Println(dp[n])
}
